import {assert} from 'chai';
import {beforeEach, describe, it} from 'mocha';
import sinon from 'sinon';

import {renderElementIntoDOM} from '../../testing/DOMHelpers.js';

import * as Console from './console.js';

describe('ConsoleViewport', () => {
  let viewport: Console.ConsoleViewport.ConsoleViewport;
  let mockProvider: MockProvider;
  const viewportHeight = 200;  // Matching layout test
  const viewportWidth = 600;   // Matching layout test

  class MockProvider implements Console.ConsoleViewport.ConsoleViewportProvider {
    itemHeights: number[] = [];
    itemElements: Console.ConsoleViewport.ConsoleViewportElement[] = [];
    minimumRowHeightValue = 16;  // Default from ConsoleViewMessage

    fastHeight(index: number): number {
      return this.itemHeights[index] ?? this.minimumRowHeightValue;
    }

    itemCount(): number {
      return this.itemHeights.length;
    }

    minimumRowHeight(): number {
      return this.minimumRowHeightValue;
    }

    itemElement(index: number): Console.ConsoleViewport.ConsoleViewportElement|null {
      if (this.itemElements[index]) {
        return this.itemElements[index];
      }
      // For these tests, we only need the element's offsetHeight.
      const mockElement = document.createElement('div');
      mockElement.style.height = `${this.itemHeights[index] ?? this.minimumRowHeightValue}px`;
      Object.defineProperty(
          mockElement, 'offsetHeight',
          {value: this.itemHeights[index] ?? this.minimumRowHeightValue, configurable: true});
      // Mock the ConsoleViewportElement interface methods
      return {
        willHide: () => {},
        wasShown: () => {},
        element: () => mockElement,
        focusLastChildOrSelf: () => {},
      };
    }

    setItems(heights: number[]): void {
      this.itemHeights = heights;
    }

    setItemElements(elements: Console.ConsoleViewport.ConsoleViewportElement[]): void {
      this.itemElements = elements;
    }
  }

  beforeEach(() => {
    mockProvider = new MockProvider();
    viewport = new Console.ConsoleViewport.ConsoleViewport(mockProvider);
    // Simulate setting dimensions like ConsoleTestRunner.fixConsoleViewportDimensions
    viewport.element.style.width = `${viewportWidth}px`;
    viewport.element.style.height = `${viewportHeight}px`;
    // Need to append to DOM for offsetHeight/clientHeight to work
    renderElementIntoDOM(viewport.element);
  });

  /** Helper to set items and refresh the viewport **/
  function setItemsAndRefresh(heights: number[]): void {
    mockProvider.setItems(heights);
    viewport.invalidate();  // This calls rebuildCumulativeHeights and refresh
  }

  function changeItemHeight(index: number, newHeight: number): void {
    mockProvider.itemHeights[index] = newHeight;
    // Simulate the element's height changing in the DOM for the viewport's calculations
    const renderedElement = viewport.renderedElementAt(index);
    if (renderedElement) {
      Object.defineProperty(renderedElement, 'offsetHeight', {value: newHeight, configurable: true});
    }
    // Invalidate to rebuild cumulative heights and then refresh
    viewport.invalidate();
  }

  /** Helper to simulate scrolling and refresh **/
  function scrollTo(scrollTop: number): void {
    viewport.element.scrollTop = scrollTop;
    viewport.refresh();
  }

  /** Helper to calculate expected cumulative heights **/
  function calculateCumulativeHeights(itemHeights: number[]): number[] {
    const cumulative = new Array(itemHeights.length);
    let currentHeight = 0;
    for (let i = 0; i < itemHeights.length; ++i) {
      currentHeight += itemHeights[i];
      cumulative[i] = currentHeight;
    }
    return cumulative;
  }

  /** Helper to calculate expected visible indices based on scroll and heights **/
  function getExpectedVisibleIndices(
      scrollTop: number, viewportHeight: number, cumulativeHeights: number[]): {first: number, last: number} {
    if (cumulativeHeights.length === 0) {
      return {first: -1, last: -1};
    }

    // Find the first visible index: the first item whose bottom is below scrollTop.
    let first = -1;
    for (let i = 0; i < cumulativeHeights.length; ++i) {
      if (cumulativeHeights[i] > scrollTop) {
        first = i;
        break;
      }
    }

    if (first === -1) {
      // No items are visible from the top.
      return {first: -1, last: -1};
    }

    // Find the last visible index: the last item whose top is above scrollTop + viewportHeight.
    let last = -1;
    const scrollBottom = scrollTop + viewportHeight;
    for (let i = cumulativeHeights.length - 1; i >= 0; --i) {
      const itemTop = i === 0 ? 0 : cumulativeHeights[i - 1];
      if (itemTop < scrollBottom) {
        last = i;
        break;
      }
    }

    // Ensure the calculated range is valid.
    if (last < first) {
      return {first: -1, last: -1};
    }

    return {first, last};
  }

  it('copies only visible text from elements with hidden children', () => {
    const messageElement = document.createElement('div');
    messageElement.innerHTML = '<span>visible message</span><div style="display: none">hidden stack</div>';
    Object.defineProperty(messageElement, 'offsetHeight', {value: 20, configurable: true});
    mockProvider.setItems([20]);
    mockProvider.setItemElements([{
      willHide: () => {},
      wasShown: () => {},
      element: () => messageElement,
      focusLastChildOrSelf: () => {},
    }]);
    viewport.invalidate();

    const range = document.createRange();
    range.selectNodeContents(messageElement);
    const selection = window.getSelection();
    selection?.removeAllRanges();
    selection?.addRange(range);

    let copiedText = '';
    const copyEvent = new Event('copy', {bubbles: true, cancelable: true}) as ClipboardEvent;
    Object.defineProperty(copyEvent, 'clipboardData', {
      value: {
        setData: (_format: string, data: string) => {
          copiedText = data;
        },
      },
    });
    viewport.element.dispatchEvent(copyEvent);

    assert.strictEqual(copiedText, 'visible message');
  });

  it('copies full text when hidden child becomes visible', () => {
    const messageElement = document.createElement('div');
    const hiddenDiv = document.createElement('div');
    hiddenDiv.textContent = ' expanded stack';
    hiddenDiv.style.display = 'none';
    messageElement.appendChild(document.createTextNode('visible message'));
    messageElement.appendChild(hiddenDiv);

    Object.defineProperty(messageElement, 'offsetHeight', {value: 20, configurable: true});
    mockProvider.setItems([20]);
    mockProvider.setItemElements([{
      willHide: () => {},
      wasShown: () => {},
      element: () => messageElement,
      focusLastChildOrSelf: () => {},
    }]);
    viewport.invalidate();

    // Now reveal it
    hiddenDiv.style.display = 'block';

    const range = document.createRange();
    range.selectNodeContents(messageElement);
    const selection = window.getSelection();
    selection?.removeAllRanges();
    selection?.addRange(range);

    let copiedText = '';
    const copyEvent = new Event('copy', {bubbles: true, cancelable: true}) as ClipboardEvent;
    Object.defineProperty(copyEvent, 'clipboardData', {
      value: {
        setData: (_format: string, data: string) => {
          copiedText = data;
        },
      },
    });
    viewport.element.dispatchEvent(copyEvent);

    assert.strictEqual(copiedText, 'visible message expanded stack');
  });

  it('copies visible text from virtualized elements scrolled out of the DOM', () => {
    const itemHeight0 = 300;
    const itemHeight1 = 600;
    const messageElement0 = document.createElement('div');
    messageElement0.style.height = `${itemHeight0}px`;
    messageElement0.innerHTML = '<span>item 0 visible</span><div class="hidden-stack-trace">item 0 hidden stack</div>';
    Object.defineProperty(messageElement0, 'offsetHeight', {value: itemHeight0, configurable: true});

    const messageElement1 = document.createElement('div');
    messageElement1.style.height = `${itemHeight1}px`;
    messageElement1.innerHTML = '<span>item 1 visible</span><div class="hidden-stack-trace">item 1 hidden stack</div>';
    Object.defineProperty(messageElement1, 'offsetHeight', {value: itemHeight1, configurable: true});

    mockProvider.setItems([itemHeight0, itemHeight1]);
    mockProvider.setItemElements([
      {willHide: () => {}, wasShown: () => {}, element: () => messageElement0, focusLastChildOrSelf: () => {}},
      {willHide: () => {}, wasShown: () => {}, element: () => messageElement1, focusLastChildOrSelf: () => {}},
    ]);
    viewport.invalidate();

    // Scroll down so item 0 is scrolled out of the viewport and removed by partialViewportUpdate
    scrollTo(500);

    // Verify item 0 was removed from the DOM by virtualization
    assert.isFalse(messageElement0.isConnected);

    // Select all content across the viewport
    const range = document.createRange();
    range.selectNodeContents(viewport.element);
    const selection = window.getSelection();
    selection?.removeAllRanges();
    selection?.addRange(range);

    let copiedText = '';
    const copyEvent = new Event('copy', {bubbles: true, cancelable: true}) as ClipboardEvent;
    Object.defineProperty(copyEvent, 'clipboardData', {
      value: {
        setData: (_format: string, data: string) => {
          copiedText = data;
        },
      },
    });
    viewport.element.dispatchEvent(copyEvent);

    assert.include(copiedText, 'item 0 visible');
    assert.notInclude(copiedText, 'item 0 hidden stack');
    assert.include(copiedText, 'item 1 visible');
    assert.notInclude(copiedText, 'item 1 hidden stack');
  });

  it('should report -1 for first and last visible index when empty', () => {
    setItemsAndRefresh([]);
    assert.strictEqual(viewport.firstVisibleIndex(), -1);
    assert.strictEqual(viewport.lastVisibleIndex(), -1);
  });

  it('should report correct visible indices for uniform height items at the top', () => {
    const itemHeight = 20;
    const itemCount = 100;
    const heights = Array(itemCount).fill(itemHeight);
    setItemsAndRefresh(heights);

    const cumulativeHeights = calculateCumulativeHeights(heights);
    const expected = getExpectedVisibleIndices(0, viewportHeight, cumulativeHeights);

    assert.strictEqual(viewport.firstVisibleIndex(), expected.first);
    assert.strictEqual(viewport.lastVisibleIndex(), expected.last);
  });

  it('should report correct visible indices for uniform height items when scrolled down', () => {
    const itemHeight = 20;
    const itemCount = 100;
    const heights = Array(itemCount).fill(itemHeight);
    setItemsAndRefresh(heights);

    const scrollTop = 500;
    scrollTo(scrollTop);

    const cumulativeHeights = calculateCumulativeHeights(heights);
    const expected = getExpectedVisibleIndices(scrollTop, viewportHeight, cumulativeHeights);
    assert.strictEqual(viewport.firstVisibleIndex(), expected.first);
    assert.strictEqual(viewport.lastVisibleIndex(), expected.last);
  });

  it('should report correct visible indices for uniform height items at the bottom', () => {
    const itemHeight = 20;
    const itemCount = 100;
    const heights = Array(itemCount).fill(itemHeight);
    setItemsAndRefresh(heights);

    const cumulativeHeights = calculateCumulativeHeights(heights);
    const totalHeight = cumulativeHeights[cumulativeHeights.length - 1];
    const scrollTop = totalHeight - viewportHeight;
    scrollTo(scrollTop);

    const expected = getExpectedVisibleIndices(scrollTop, viewportHeight, cumulativeHeights);

    assert.strictEqual(viewport.firstVisibleIndex(), expected.first);
    assert.strictEqual(viewport.lastVisibleIndex(), expected.last);
  });

  it('should report correct visible indices for varying height items at the top', () => {
    const heights = [30, 20, 40, 15, 25, 50, 10, 35, 20, 45, 30, 20, 40, 15, 25, 50, 10, 35, 20, 45];  // 20 items
    setItemsAndRefresh(heights);

    const cumulativeHeights = calculateCumulativeHeights(heights);
    const expected = getExpectedVisibleIndices(0, viewportHeight, cumulativeHeights);

    assert.strictEqual(viewport.firstVisibleIndex(), expected.first);
    assert.strictEqual(viewport.lastVisibleIndex(), expected.last);
  });

  it('should report correct visible indices for varying height items when scrolled down', () => {
    const heights = [30, 20, 40, 15, 25, 50, 10, 35, 20, 45, 30, 20, 40, 15, 25, 50, 10, 35, 20, 45];  // 20 items
    setItemsAndRefresh(heights);

    const scrollTop = 150;
    scrollTo(scrollTop);

    const cumulativeHeights = calculateCumulativeHeights(heights);
    const expected = getExpectedVisibleIndices(scrollTop, viewportHeight, cumulativeHeights);

    assert.strictEqual(viewport.firstVisibleIndex(), expected.first);
    assert.strictEqual(viewport.lastVisibleIndex(), expected.last);
  });

  it('should report correct visible indices for varying height items at the bottom', () => {
    const heights = [30, 20, 40, 15, 25, 50, 10, 35, 20, 45, 30, 20, 40, 15, 25, 50, 10, 35, 20, 45];  // 20 items
    setItemsAndRefresh(heights);

    const cumulativeHeights = calculateCumulativeHeights(heights);
    const totalHeight = cumulativeHeights[cumulativeHeights.length - 1];
    const scrollTop = totalHeight - viewportHeight;
    scrollTo(scrollTop);

    const expected = getExpectedVisibleIndices(scrollTop, viewportHeight, cumulativeHeights);
    assert.strictEqual(viewport.firstVisibleIndex(), expected.first);
    assert.strictEqual(viewport.lastVisibleIndex(), expected.last);
  });

  it('should update cumulative heights when item heights change after initial render', () => {
    const initialHeights = Array(10).fill(40);
    setItemsAndRefresh(initialHeights);

    // Simulate a height change for a rendered item
    const changedIndex = 2;  // Must be within the initially rendered range
    const newHeight = 50;
    const updatedHeights = [...initialHeights];
    updatedHeights[changedIndex] = newHeight;

    // Change element's height.
    changeItemHeight(changedIndex, newHeight);

    // Simulate a scroll that would require recalculating heights
    const scrollTop = 100;
    scrollTo(scrollTop);  // This should trigger rebuildCumulativeHeightsIfNeeded

    const cumulativeHeights = calculateCumulativeHeights(updatedHeights);
    const expected = getExpectedVisibleIndices(scrollTop, viewportHeight, cumulativeHeights);

    assert.strictEqual(viewport.firstVisibleIndex(), expected.first);
    assert.strictEqual(viewport.lastVisibleIndex(), expected.last);
  });

  // Test forceScrollItemToBeFirst and forceScrollItemToBeLast
  it('should force an item to be the first visible item', () => {
    const itemHeight = 20;
    const itemCount = 100;
    const heights = Array(itemCount).fill(itemHeight);
    setItemsAndRefresh(heights);

    const targetIndex = 50;
    viewport.forceScrollItemToBeFirst(targetIndex);

    const cumulativeHeights = calculateCumulativeHeights(heights);
    const expectedScrollTop = targetIndex > 0 ? cumulativeHeights[targetIndex - 1] : 0;
    const expected = getExpectedVisibleIndices(expectedScrollTop, viewportHeight, cumulativeHeights);

    assert.strictEqual(viewport.firstVisibleIndex(), expected.first);
    assert.strictEqual(viewport.lastVisibleIndex(), expected.last);
    assert.strictEqual(viewport.element.scrollTop, expectedScrollTop);
  });

  it('should force an item to be the last visible item', () => {
    const itemHeight = 20;
    const itemCount = 100;
    const heights = Array(itemCount).fill(itemHeight);
    setItemsAndRefresh(heights);

    const targetIndex = 50;
    viewport.forceScrollItemToBeLast(targetIndex);

    const cumulativeHeights = calculateCumulativeHeights(heights);
    const expectedScrollTop = cumulativeHeights[targetIndex] - viewportHeight;
    const expected = getExpectedVisibleIndices(expectedScrollTop, viewportHeight, cumulativeHeights);

    assert.strictEqual(viewport.firstVisibleIndex(), expected.first);
    assert.strictEqual(viewport.lastVisibleIndex(), expected.last);
    assert.strictEqual(viewport.element.scrollTop, expectedScrollTop);
  });

  describe('stick-to-bottom with expanding objects', () => {
    const ITEM_COUNT = 150;
    const INITIAL_ITEM_HEIGHT = 20;
    const EXPANDED_ITEM_HEIGHT_INCREASE = 80;  // Makes item 100px tall

    function populateViewport(itemCount: number, itemHeight: number): void {
      const heights = Array(itemCount).fill(itemHeight);
      setItemsAndRefresh(heights);
    }

    function forceSelectAndFocus(index: number): void {
      viewport.scrollItemIntoView(index);
      const elementToFocus = viewport.renderedElementAt(index);
      if (elementToFocus) {
        elementToFocus.focus();
      }
      // Refresh to ensure onFocusIn logic (like setting virtualSelectedIndex) and updateFocusedItem are processed.
      viewport.refresh();
    }

    function isElementFullyVisible(index: number): boolean {
      const selectedElement = viewport.renderedElementAt(index);
      if (!selectedElement) {
        return false;
      }
      const selectedRect = selectedElement.getBoundingClientRect();
      const viewportRect = viewport.element.getBoundingClientRect();
      // Using a small tolerance like in the layout test
      const tolerance = 2.5;
      return (
          selectedRect.top + tolerance >= viewportRect.top && selectedRect.bottom - tolerance <= viewportRect.bottom);
    }

    function getInfo(selectedIndex: number): {isAtBottom: boolean, shouldStick: boolean, selectedVisible: boolean} {
      viewport.refresh();  // Ensure viewport is up-to-date before getting info
      const isAtBottom =
          (viewport.element.scrollHeight - viewport.element.scrollTop - viewport.element.clientHeight) < 1;
      const shouldStick = viewport.stickToBottom();
      const selectedVisible = isElementFullyVisible(selectedIndex);
      return {isAtBottom, shouldStick, selectedVisible};
    }

    beforeEach(() => {
      populateViewport(ITEM_COUNT, INITIAL_ITEM_HEIGHT);
    });

    it('keeps last visible object in view when expanded/collapsed if scrolled to bottom', () => {
      // Scroll to bottom
      scrollTo(viewport.element.scrollHeight - viewport.element.clientHeight);
      viewport.setStickToBottom(true);  // Explicitly set stick to bottom
      viewport.refresh();

      const lastItemIndex = ITEM_COUNT - 1;
      forceSelectAndFocus(lastItemIndex);

      let info = getInfo(lastItemIndex);
      assert.isTrue(info.isAtBottom, 'Initial: Should be at bottom');
      assert.isTrue(info.shouldStick, 'Initial: Should stick to bottom');
      assert.isTrue(info.selectedVisible, 'Initial: Selected item should be visible');

      // Expand object
      changeItemHeight(lastItemIndex, INITIAL_ITEM_HEIGHT + EXPANDED_ITEM_HEIGHT_INCREASE);

      info = getInfo(lastItemIndex);
      assert.isTrue(info.isAtBottom, 'After expand: Should be at bottom');
      assert.isTrue(info.shouldStick, 'After expand: Should stick to bottom');
      assert.isTrue(info.selectedVisible, 'After expand: Selected item should be visible');

      // Collapse object
      changeItemHeight(lastItemIndex, INITIAL_ITEM_HEIGHT);

      info = getInfo(lastItemIndex);
      assert.isTrue(info.isAtBottom, 'After collapse: Should be at bottom');
      assert.isTrue(info.shouldStick, 'After collapse: Should stick to bottom');
      assert.isTrue(info.selectedVisible, 'After collapse: Selected item should be visible');
    });

    it('keeps first fully visible object in view when expanded/collapsed if not scrolled to bottom', () => {
      // Scroll somewhere in the middle, not at the bottom
      const scrollTop = 100;
      scrollTo(scrollTop);               // This also calls refresh
      viewport.setStickToBottom(false);  // Explicitly set stick to bottom to false
      viewport.refresh();

      // The layout test uses `viewport.firstVisibleIndex() + 1`.
      const targetIndex = viewport.firstVisibleIndex() + 1;
      assert.isBelow(targetIndex, ITEM_COUNT, 'Target index should be within bounds');

      forceSelectAndFocus(targetIndex);

      let info = getInfo(targetIndex);
      assert.isFalse(info.isAtBottom, 'Initial: Should not be at bottom');
      assert.isFalse(info.shouldStick, 'Initial: Should not stick to bottom');
      assert.isTrue(info.selectedVisible, 'Initial: Selected item should be visible');

      // Expand object
      changeItemHeight(targetIndex, INITIAL_ITEM_HEIGHT + EXPANDED_ITEM_HEIGHT_INCREASE);

      info = getInfo(targetIndex);
      assert.isFalse(info.isAtBottom, 'After expand: Should not be at bottom');
      assert.isFalse(info.shouldStick, 'After expand: Should not stick to bottom');
      assert.isTrue(info.selectedVisible, 'After expand: Selected item should be visible');

      // Collapse object
      changeItemHeight(targetIndex, INITIAL_ITEM_HEIGHT);

      info = getInfo(targetIndex);
      assert.isFalse(info.isAtBottom, 'After collapse: Should not be at bottom');
      assert.isFalse(info.shouldStick, 'After collapse: Should not stick to bottom');
      assert.isTrue(info.selectedVisible, 'After collapse: Selected item should be visible');
    });
  });

  describe('declarative DOM reconciliation', () => {
    function createViewportElement(height: number) {
      const element = document.createElement('div');
      element.style.height = `${height}px`;
      Object.defineProperty(element, 'offsetHeight', {value: height, configurable: true});
      return {
        willHide: sinon.spy(),
        wasShown: sinon.spy(),
        element: () => element,
        focusLastChildOrSelf: () => {},
      };
    }

    it('renders empty gaps and unfocusable content synchronously on construction', () => {
      assert.strictEqual(viewport.element.style.overflow, 'auto');
      const [topGap, content, bottomGap] = viewport.element.children as HTMLCollectionOf<HTMLElement>;
      assert.strictEqual(content, viewport.contentElement());
      assert.strictEqual(topGap.style.height, '0px');
      assert.strictEqual(bottomGap.style.height, '0px');
      assert.strictEqual(content.tabIndex, -1);
    });

    it('updates active items, gap heights, and lifecycle callbacks on scroll', () => {
      const items = Array.from({length: 100}, () => createViewportElement(20));
      mockProvider.setItemElements(items);
      setItemsAndRefresh(Array(100).fill(20));

      sinon.assert.calledOnce(items[0].wasShown);
      sinon.assert.notCalled(items[25].wasShown);
      assert.strictEqual((viewport.contentElement() as HTMLElement).tabIndex, 0);

      scrollTo(1000);
      const [topGap, , bottomGap] = viewport.element.children as HTMLCollectionOf<HTMLElement>;
      assert.strictEqual(topGap.style.height, '900px');
      assert.strictEqual(bottomGap.style.height, '600px');
      sinon.assert.calledOnce(items[0].willHide);
      sinon.assert.calledOnce(items[45].wasShown);
    });

    it('preserves trailing children appended to the viewport element by its owner', () => {
      const prompt = document.createElement('div');
      viewport.element.appendChild(prompt);
      setItemsAndRefresh(Array(100).fill(20));
      scrollTo(1000);
      setItemsAndRefresh(Array(50).fill(20));
      assert.strictEqual(viewport.element.lastElementChild, prompt);
    });
  });

  describe('DOM virtualization and lifecycle', () => {
    const ITEM_HEIGHT = 20;
    const SMALL_COUNT = 3;
    const VISIBLE_COUNT = 10;
    const MAX_ACTIVE_COUNT = 20;

    interface TrackedItem extends Console.ConsoleViewport.ConsoleViewportElement {
      wasShownSpy: sinon.SinonSpy;
      willHideSpy: sinon.SinonSpy;
    }

    function createTrackedItems(count: number, startIndex = 0): TrackedItem[] {
      const items: TrackedItem[] = [];
      for (let i = 0; i < count; ++i) {
        const el = document.createElement('div');
        el.textContent = `Message #${startIndex + i}`;
        el.style.height = `${ITEM_HEIGHT}px`;
        Object.defineProperty(el, 'offsetHeight', {value: ITEM_HEIGHT, configurable: true});
        const wasShownSpy = sinon.spy();
        const willHideSpy = sinon.spy();
        items.push({
          willHide: willHideSpy,
          wasShown: wasShownSpy,
          element: () => el,
          focusLastChildOrSelf: () => {},
          wasShownSpy,
          willHideSpy,
        });
      }
      return items;
    }

    function setTrackedItems(items: TrackedItem[]): void {
      mockProvider.minimumRowHeightValue = ITEM_HEIGHT;
      mockProvider.setItems(Array(items.length).fill(ITEM_HEIGHT));
      mockProvider.setItemElements(items);
      viewport.invalidate();
    }

    it('renders and shows all items when count is smaller than visible viewport', () => {
      const items = createTrackedItems(SMALL_COUNT);
      setTrackedItems(items);
      viewport.forceScrollItemToBeFirst(0);

      assert.strictEqual(viewport.contentElement().childElementCount, SMALL_COUNT);
      assert.isTrue(items.every(item => item.element().isConnected));
      assert.strictEqual(viewport.firstVisibleIndex(), 0);
      assert.strictEqual(viewport.lastVisibleIndex(), SMALL_COUNT - 1);
      for (const item of items) {
        sinon.assert.calledOnce(item.wasShownSpy);
        sinon.assert.notCalled(item.willHideSpy);
      }
    });

    it('renders extra items beyond visible count when within active window', () => {
      const items = createTrackedItems(VISIBLE_COUNT + 1);
      setTrackedItems(items);
      viewport.forceScrollItemToBeFirst(0);

      assert.strictEqual(viewport.contentElement().childElementCount, VISIBLE_COUNT + 1);
      assert.isTrue(items.every(item => item.element().isConnected));
      assert.strictEqual(viewport.firstVisibleIndex(), 0);
      assert.strictEqual(viewport.lastVisibleIndex(), VISIBLE_COUNT - 1);
    });

    it('renders up to max active items in the DOM when scrolled to top', () => {
      const items = createTrackedItems(MAX_ACTIVE_COUNT);
      setTrackedItems(items);
      viewport.forceScrollItemToBeFirst(0);

      assert.strictEqual(viewport.contentElement().childElementCount, MAX_ACTIVE_COUNT);
      assert.isTrue(items.every(item => item.element().isConnected));
      assert.strictEqual(viewport.firstVisibleIndex(), 0);
      assert.strictEqual(viewport.lastVisibleIndex(), VISIBLE_COUNT - 1);
    });

    it('caps rendered DOM items at max active count when total items exceed it', () => {
      const items = createTrackedItems(MAX_ACTIVE_COUNT + SMALL_COUNT);
      setTrackedItems(items);
      viewport.forceScrollItemToBeFirst(0);

      assert.strictEqual(viewport.contentElement().childElementCount, MAX_ACTIVE_COUNT);
      assert.isTrue(items.slice(0, MAX_ACTIVE_COUNT).every(item => item.element().isConnected));
      assert.isTrue(items.slice(MAX_ACTIVE_COUNT).every(item => !item.element().isConnected));
      assert.strictEqual(viewport.firstVisibleIndex(), 0);
      assert.strictEqual(viewport.lastVisibleIndex(), VISIBLE_COUNT - 1);
    });

    it('keeps all items in DOM without show or hide calls when scrolling within partial active window', () => {
      // With 14 items (280px total) in a 200px viewport, scrolling to the bottom sets scrollTop to 80px,
      // which stays within the 100px active buffer above the visible viewport.
      const partialActiveCount = 14;
      const items = createTrackedItems(partialActiveCount);
      setTrackedItems(items);
      viewport.forceScrollItemToBeFirst(0);
      for (const item of items) {
        item.wasShownSpy.resetHistory();
        item.willHideSpy.resetHistory();
      }

      scrollTo(viewport.element.scrollHeight - viewport.element.clientHeight);

      for (const item of items) {
        sinon.assert.notCalled(item.wasShownSpy);
        sinon.assert.notCalled(item.willHideSpy);
      }
      assert.strictEqual(viewport.contentElement().childElementCount, partialActiveCount);
      assert.isTrue(items.every(item => item.element().isConnected));
      assert.strictEqual(viewport.firstVisibleIndex(), 4);
      assert.strictEqual(viewport.lastVisibleIndex(), 13);
    });

    it('adds bottom items and hides top items when scrolling beyond active window', () => {
      const items = createTrackedItems(MAX_ACTIVE_COUNT + 1);
      setTrackedItems(items);
      viewport.forceScrollItemToBeFirst(0);
      assert.isFalse(items[MAX_ACTIVE_COUNT].element().isConnected);
      for (const item of items) {
        item.wasShownSpy.resetHistory();
        item.willHideSpy.resetHistory();
      }

      scrollTo(viewport.element.scrollHeight - viewport.element.clientHeight - 3);

      // At scrollTop = 217px, the 100px active buffer above starts at 118px (index 5), evicting items 0..4.
      for (const item of items.slice(0, 5)) {
        sinon.assert.calledOnce(item.willHideSpy);
        sinon.assert.notCalled(item.wasShownSpy);
        assert.isFalse(item.element().isConnected);
      }
      for (const item of items.slice(5, MAX_ACTIVE_COUNT)) {
        sinon.assert.notCalled(item.wasShownSpy);
        sinon.assert.notCalled(item.willHideSpy);
        assert.isTrue(item.element().isConnected);
      }
      sinon.assert.calledOnce(items[MAX_ACTIVE_COUNT].wasShownSpy);
      sinon.assert.notCalled(items[MAX_ACTIVE_COUNT].willHideSpy);
      assert.isTrue(items[MAX_ACTIVE_COUNT].element().isConnected);
    });

    it('does not reconnect or re-show existing DOM elements when appending items', () => {
      const firstBatch = createTrackedItems(SMALL_COUNT, 0);
      setTrackedItems(firstBatch);

      const addedNodes: Node[] = [];
      const removedNodes: Node[] = [];
      const observer = new MutationObserver(records => {
        for (const record of records) {
          addedNodes.push(...record.addedNodes);
          removedNodes.push(...record.removedNodes);
        }
      });
      observer.observe(viewport.contentElement(), {childList: true});
      try {
        const secondBatch = createTrackedItems(SMALL_COUNT, SMALL_COUNT);
        const allItems = [...firstBatch, ...secondBatch];
        setTrackedItems(allItems);
        observer.takeRecords().forEach(record => {
          addedNodes.push(...record.addedNodes);
          removedNodes.push(...record.removedNodes);
        });

        for (const item of allItems) {
          sinon.assert.calledOnce(item.wasShownSpy);
          sinon.assert.notCalled(item.willHideSpy);
        }
        // Lit adds comment markers for the new parts; only elements matter here.
        assert.isEmpty(removedNodes.filter(node => node instanceof Element));
        assert.deepEqual(addedNodes.filter(node => node instanceof Element), secondBatch.map(item => item.element()));
      } finally {
        observer.disconnect();
      }
    });

    it('reorders existing DOM elements without firing wasShown or willHide', () => {
      const items = createTrackedItems(SMALL_COUNT);
      setTrackedItems(items);
      for (const item of items) {
        item.wasShownSpy.resetHistory();
        item.willHideSpy.resetHistory();
      }

      const reordered = [items[1], items[0], items[2]];
      setTrackedItems(reordered);

      for (const item of items) {
        sinon.assert.notCalled(item.wasShownSpy);
        sinon.assert.notCalled(item.willHideSpy);
      }
      assert.deepEqual(Array.from(viewport.contentElement().children), reordered.map(item => item.element()));
    });
  });
});
